using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "StunnedEffect", menuName = "Data/Battle/Effects/Enemy/Stunned Effect")]
public class StunnedEffect : Effect
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		if (amount >= EffectsValues.INFINITY)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("StunnedInf_D");
		}
		return base.GetEffectDescription(amount);
	}
}
